// Guards the 50 synthetic bank statements in ./synthetic-statements. They are regenerated by
// packages/data/scripts/gen-synthetic-statements.mjs; if a regeneration (or a hand edit) breaks
// any of the promises the README makes about them, this is where it shows up.
import { readFileSync, readdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { COST_CATEGORIES } from '@lifeguessr/types';

const dir = fileURLToPath(new URL('./synthetic-statements/', import.meta.url));
const read = (name: string) => readFileSync(dir + name, 'utf8');

// RFC 4180-ish reader, same rules as the app's in-browser CSV reader: quoted cells, doubled
// quotes, CRLF or LF, blank lines skipped.
function rowsOf(text: string): string[][] {
  const rows: string[][] = [];
  let row: string[] = [];
  let cell = '';
  let quoted = false;
  const finish = () => {
    row.push(cell);
    if (row.some((v) => v.trim() !== '')) rows.push(row);
    row = [];
    cell = '';
  };
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (quoted) {
      if (c === '"' && text[i + 1] === '"') {
        cell += '"';
        i++;
      } else if (c === '"') quoted = false;
      else cell += c;
    } else if (c === '"') quoted = true;
    else if (c === ',') {
      row.push(cell);
      cell = '';
    } else if (c === '\n' || c === '\r') {
      if (c === '\r' && text[i + 1] === '\n') i++;
      finish();
    } else cell += c;
  }
  if (cell !== '' || row.length) finish();
  return rows;
}

// Column detection copied from the app's CSV reader, so a layout the reader can't auto-detect
// fails here first.
function detect(header: string[]) {
  const h = header.map((x) => x.toLowerCase().trim());
  const find = (r: RegExp) => h.findIndex((x) => r.test(x));
  return {
    date: find(/^(date|transaction date|posted date|posting date)$/),
    label: find(/description|merchant|memo|payee/),
    amount: find(/^amount$/),
    debit: find(/debit|withdrawal/),
    credit: find(/credit|deposit/),
    balance: find(/^(balance|running bal\.)$/),
  };
}

const MONEY = /^-?(?:\d+|\d{1,3}(?:,\d{3})+)\.\d{2}$/;
const toCents = (s: string) => (s === '' ? 0 : Math.round(Number(s.replace(/,/g, '')) * 100));
function parseDate(s: string) {
  const iso = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  const us = s.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  const [y, m, d] = iso ? [+iso[1], +iso[2], +iso[3]] : us ? [+us[3], +us[1], +us[2]] : [NaN, NaN, NaN];
  const t = new Date(Date.UTC(y, m - 1, d));
  if (t.getUTCFullYear() !== y || t.getUTCMonth() !== m - 1 || t.getUTCDate() !== d) throw new Error(`bad date ${s}`);
  return { y, m, d, dow: t.getUTCDay(), key: `${y}-${String(m).padStart(2, '0')}` };
}
const FED_HOLIDAYS = new Set(['2026-09-07', '2026-10-12', '2026-11-11']);

const files = readdirSync(dir).filter((f) => f.endsWith('.csv')).sort();
const keyRows = rowsOf(read('labels/answer-key.csv'));
const households = rowsOf(read('labels/households.csv'));
const labels = new Map<string, { category: string; kind: string; oneOff: string; basis: string }[]>();
for (const [file, , category, kind, oneOff, basis] of keyRows.slice(1)) {
  if (!labels.has(file!)) labels.set(file!, []);
  labels.get(file!)!.push({ category: category!, kind: kind!, oneOff: oneOff!, basis: basis! });
}

type Tx = { date: ReturnType<typeof parseDate>; label: string; cents: number; balance: number | null; category: string; kind: string; oneOff: boolean; basis: string };
const parsed = new Map<string, { header: string[]; tx: Tx[] }>();
for (const f of files) {
  const rows = rowsOf(read(f).replace(/^\uFEFF/, ''));
  const header = rows[0]!;
  const c = detect(header);
  const key = labels.get(f) ?? [];
  const tx = rows.slice(1).map((r, i) => {
    const signed = c.amount >= 0 ? toCents(r[c.amount]!) : toCents(r[c.credit]!) - toCents(r[c.debit]!);
    return {
      date: parseDate(r[c.date]!),
      label: r[c.label]!,
      cents: signed,
      balance: c.balance >= 0 ? toCents(r[c.balance]!) : null,
      category: key[i]?.category ?? '',
      kind: key[i]?.kind ?? '',
      oneOff: key[i]?.oneOff === 'true',
      basis: key[i]?.basis ?? '',
    };
  });
  parsed.set(f, { header, tx });
}

describe('synthetic statements', () => {
  it('are 50 CSV exports, each listed once in households.csv', () => {
    expect(files).toHaveLength(50);
    expect(households.slice(1).map((r) => r[0]).sort()).toEqual(files);
  });

  it('use headers, dates and amounts the app reader auto-detects', () => {
    for (const f of files) {
      const rows = rowsOf(read(f).replace(/^\uFEFF/, ''));
      const c = detect(rows[0]!);
      expect(c.date, f).toBeGreaterThanOrEqual(0);
      expect(c.label, f).toBeGreaterThanOrEqual(0);
      expect(c.amount >= 0 || c.debit >= 0, f).toBe(true);
      for (const r of rows.slice(1)) {
        expect(r, `${f}: ${r.join('|')}`).toHaveLength(rows[0]!.length);
        expect(() => parseDate(r[c.date]!)).not.toThrow();
        expect(r[c.label]!.trim(), f).not.toBe('');
        if (c.amount >= 0) expect(r[c.amount], f).toMatch(MONEY);
        else {
          const debit = r[c.debit]!;
          const credit = r[c.credit]!;
          expect((debit === '') !== (credit === ''), `${f}: exactly one of debit/credit`).toBe(true);
          expect(debit || credit, f).toMatch(MONEY);
        }
      }
    }
  });

  it('have one answer-key label per row, using the app categories', () => {
    const kinds = new Set(['income', 'spend', 'refund', 'reimbursement', 'transfer_out', 'transfer_in']);
    for (const f of files) {
      const { tx } = parsed.get(f)!;
      expect(labels.get(f)?.length, f).toBe(tx.length);
      for (const t of tx) {
        expect(kinds.has(t.kind), `${f}: ${t.kind}`).toBe(true);
        expect(['merchant', 'memo', 'context'], `${f}: ${t.label}`).toContain(t.basis);
        if (t.kind === 'spend' || t.kind === 'refund') expect(COST_CATEGORIES as readonly string[], `${f}: ${t.label}`).toContain(t.category);
        else expect(t.category, `${f}: ${t.label}`).toBe('');
        // money out is spending or a transfer out; money in is anything else
        if (t.kind === 'spend' || t.kind === 'transfer_out') expect(t.cents, `${f}: ${t.label}`).toBeLessThan(0);
        else expect(t.cents, `${f}: ${t.label}`).toBeGreaterThan(0);
      }
    }
  });

  it('keep running balances consistent, row by row', () => {
    for (const f of files) {
      const { header, tx } = parsed.get(f)!;
      if (tx[0]!.balance === null) continue;
      // "Date" exports (oldest first) vs "Posting Date" exports (newest first)
      const ordered = header[0] === 'Date' ? tx : [...tx].reverse();
      for (let i = 1; i < ordered.length; i++) expect(ordered[i - 1]!.balance! + ordered[i]!.cents, `${f} row ${i}`).toBe(ordered[i]!.balance);
    }
  });

  it('never post on a weekend or Fed holiday in posting-date exports', () => {
    for (const f of files) {
      const { header, tx } = parsed.get(f)!;
      if (!header.some((h) => /posting date|^date$/i.test(h)) || header.includes('Time')) continue;
      for (const t of tx) {
        const iso = `${t.date.key}-${String(t.date.d).padStart(2, '0')}`;
        expect(t.date.dow !== 0 && t.date.dow !== 6 && !FED_HOLIDAYS.has(iso), `${f}: ${iso} ${t.label}`).toBe(true);
      }
    }
  });

  it('cover at least three full months, each with pay and exactly one rent or mortgage payment', () => {
    for (const f of files) {
      const { tx } = parsed.get(f)!;
      const months = [...new Set(tx.map((t) => t.date.key))].sort();
      const full = months.filter((m) => m !== '2026-11');
      expect(full.length, f).toBeGreaterThanOrEqual(3);
      expect(months, f).toContain('2026-11'); // a partial current month, as a real download has
      const owner = households.find((r) => r[0] === f)![10] === 'own';
      for (const m of full) {
        const inMonth = tx.filter((t) => t.date.key === m);
        expect(inMonth.some((t) => t.kind === 'income'), `${f} ${m} has income`).toBe(true);
        const housing = inMonth.filter((t) =>
          owner ? /MTG|MORTGAGE|MR\. COOPER|PENNYMAC|NEWREZ/i.test(t.label) : t.category === 'rentUtilities' && t.cents <= -40000,
        );
        expect(housing.length, `${f} ${m} housing rows`).toBe(1);
      }
    }
  });

  it('mark person-to-person and check rows as memo or context, everything else as merchant', () => {
    const purposeOnly = /ZELLE|VENMO|CASH APP|PAY FRIENDS|^CHECK |^CHECK$|SHARE DRAFT/i;
    for (const f of files) for (const t of parsed.get(f)!.tx) {
      if (t.basis === 'merchant') expect(t.label, f).not.toMatch(/^(Zelle payment|CHECK \d|Check #?\d|SHARE DRAFT|Pay Friends)/);
      else expect(t.label, f).toMatch(purposeOnly);
    }
  });

  it('give a merchant the same category in every household', () => {
    // Person-to-person payments and checks are categorized by purpose, so they're excluded.
    const p2p = /ZELLE|VENMO|CASH APP|PAY FRIENDS|^CHECK|SHARE DRAFT|TRANSFER|DES:/i;
    const norm = (s: string) => s.toUpperCase().replace(/^(CHECKCARD( REFUND)?|POS (PURCHASE|RETURN)|REFUND -)\s*/, '').replace(/[#\d]/g, '').replace(/\s+/g, ' ').trim();
    const seen = new Map<string, string>();
    for (const f of files) {
      for (const t of parsed.get(f)!.tx) {
        if ((t.kind !== 'spend' && t.kind !== 'refund') || p2p.test(t.label)) continue;
        const k = norm(t.label);
        const prev = seen.get(k);
        if (prev) expect(t.category, `${f}: "${t.label}" was ${prev} elsewhere`).toBe(prev);
        else seen.set(k, t.category);
      }
    }
  });

  it('include raw personal names for the masker to remove', () => {
    const all = files.map((f) => read(f)).join('\n');
    expect(all).toMatch(/Zelle payment (to|from) [A-Z][a-z]+ [A-Z][a-z]+/);
    expect(all).toMatch(/Pay Friends - (Sent to|Received from) [A-Z][a-z]+ [A-Z][a-z]+/);
    expect(all).toMatch(/INDN:[A-Z]+, [A-Z]+/); // the account holder's own name, BofA style
    expect(all).toMatch(/CASH APP\*[A-Z]+ [A-Z]+/i);
  });

  it('cover every app category and every kind of row somewhere', () => {
    const cats = new Set<string>();
    const kinds = new Set<string>();
    for (const f of files) for (const t of parsed.get(f)!.tx) {
      if (t.category) cats.add(t.category);
      kinds.add(t.kind);
    }
    expect([...cats].sort()).toEqual([...COST_CATEGORIES].sort());
    expect([...kinds].sort()).toEqual(['income', 'refund', 'reimbursement', 'spend', 'transfer_in', 'transfer_out']);
  });
});
